scan_script_only_check.script:
(function(engine) {
    var cutoff = new GlideDateTime();
    cutoff.addDaysLocalTime(-90);
    var cutoffStr = cutoff.getValue();

    var gr = new GlideRecord('sysauto_script');
    gr.addQuery('active', true);
    gr.addNullQuery('run_start');
    gr.query();
    var neverRanCount = 0;

    while (gr.next()) {
        neverRanCount++;
        if (neverRanCount <= 20) {
            engine.finding.setCurrentSource(gr);
            engine.finding.setValue('finding_details',
                'Scheduled job "' + gr.getValue('name') + '" is active but has never executed (run_start is empty). It may be misconfigured or orphaned. Created by ' + (gr.getValue('sys_created_by') || 'unknown') + ' on ' + (gr.getValue('sys_created_on') || 'unknown') + '.');
            engine.finding.increment();
        }
    }

    var gr2 = new GlideRecord('sysauto_script');
    gr2.addQuery('active', true);
    gr2.addNotNullQuery('run_start');
    gr2.addQuery('run_start', '<', cutoffStr);
    gr2.query();
    var staleCount = 0;

    while (gr2.next()) {
        staleCount++;
        if (staleCount <= 20) {
            engine.finding.setCurrentSource(gr2);
            engine.finding.setValue('finding_details',
                'Scheduled job "' + gr2.getValue('name') + '" is active but last ran on ' + gr2.getValue('run_start') + ' (over 90 days ago). It may be orphaned or its schedule may be misconfigured. Created by ' + (gr2.getValue('sys_created_by') || 'unknown') + '.');
            engine.finding.increment();
        }
    }
})(engine);
